 private synchronized void append(String kind,JSONObject data)throws Exception{File j=new File(root,"journal.jsonl");if(j.length()>1024*1024||journalSeq>=512)throw new IOException("JOURNAL_QUOTA_NO_AUTO_DELETE");JSONObject record=obj("seq",journalSeq+1,"previous",journalHead,"kind",kind,"elapsedMs",SystemClock.elapsedRealtime(),"at",System.currentTimeMillis(),"data",data);String body=record.toString(),digest=Integrity02.sha(body.getBytes(StandardCharsets.UTF_8));byte[]line=obj("body",body,"sha256",digest).toString().concat("\n").getBytes(StandardCharsets.UTF_8);try(FileOutputStream out=new FileOutputStream(j,true)){out.write(line);out.getFD().sync();}syncDirectory();journalSeq++;journalHead=digest;}
 private void syncDirectory()throws Exception{if(!Files.isDirectory(root.toPath(),LinkOption.NOFOLLOW_LINKS))throw new IOException("STORE_DIRECTORY_REQUIRED");java.io.FileDescriptor fd=Os.open(root.getAbsolutePath(),OsConstants.O_RDONLY,0);try{Os.fsync(fd);}finally{Os.close(fd);}}
 private void recover()throws Exception{File j=new File(root,"journal.jsonl");if(!j.exists())return;byte[]b=Integrity02.read(new FileInputStream(j),1024*1024);String text=new String(b,StandardCharsets.UTF_8);if(!text.endsWith("\n"))throw new IOException("JOURNAL_PENDING_TAIL_READONLY");Map<String,JSONObject> pending=new LinkedHashMap<>();for(String line:text.split("\n")){JSONObject e=new JSONObject(line),r=new JSONObject(e.getString("body"));if(!Integrity02.sha(e.getString("body").getBytes(StandardCharsets.UTF_8)).equals(e.getString("sha256"))||r.getLong("seq")!=journalSeq+1||!r.getString("previous").equals(journalHead))throw new IOException("JOURNAL_CHAIN_READONLY");journalSeq++;journalHead=e.getString("sha256");String kind=r.getString("kind");JSONObject d=r.getJSONObject("data");if(kind.equals("PICKER_PENDING")){pending.put(d.getString("id"),d);operations++;}else if(d.has("id")&&!kind.equals("MIRROR_COMMITTED"))pending.remove(d.getString("id"));}for(JSONObject d:pending.values())append("UNKNOWN_AFTER_RESTART",obj("id",d.getString("id"),"reason","NO_AUTOMATIC_RETRY_OR_AUTHORITY_RESTORE","authorityRestored",false));}
 private byte[] http(String path,JSONObject body,int max)throws Exception{if(!path.startsWith("/")||path.startsWith("//"))throw new IOException("HTTP_PATH");HttpURLConnection c=(HttpURLConnection)new URL(Integrity02.ORIGIN+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(5000);c.setReadTimeout(12000);c.setRequestProperty("Origin",Integrity02.ORIGIN);c.setRequestProperty("X-Field-Android-Instance",instance);if(body!=null){if(csrf.isEmpty()){JSONObject b=new JSONObject(new String(http("/api/bootstrap",null,65536),StandardCharsets.UTF_8));csrf=b.getString("csrf");}c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("X-Field-CSRF",csrf);byte[]bytes=body.toString().getBytes(StandardCharsets.UTF_8);c.setFixedLengthStreamingMode(bytes.length);try(OutputStream out=c.getOutputStream()){out.write(bytes);}}try{if(c.getResponseCode()!=200){InputStream error=c.getErrorStream();String detail=error==null?"":new String(Integrity02.read(error,4096),StandardCharsets.UTF_8);throw new IOException("HOST_HTTP_"+c.getResponseCode()+":"+detail);}long length=c.getContentLengthLong();if(length>max)throw new IOException("HTTP_LENGTH_BOUND");try(InputStream in=c.getInputStream()){byte[]r=Integrity02.read(in,max);if(length>=0&&length!=r.length)throw new IOException("HTTP_INCOMPLETE_BODY");return r;}}finally{c.disconnect();}}
 private JSONObject loadWorkspace()throws Exception{JSONObject r=new JSONObject(new String(http("/api/native82",obj("action","load"),Integrity02.WORKSPACE_MAX),StandardCharsets.UTF_8));if(r.has("result"))r=r.getJSONObject("result");if(!r.optBoolean("ok")||r.optBoolean("pending")||r.isNull("bodyBase64"))throw new IOException("COMMITTED_WORKSPACE_REQUIRED");head=r.getString("token");return r;}
 private byte[] wrapper(JSONObject ws)throws Exception{byte[]body=android.util.Base64.decode(ws.getString("bodyBase64"),android.util.Base64.DEFAULT);if(body.length>Integrity02.WORKSPACE_MAX)throw new IOException("WORKSPACE_BOUND");JSONObject doc=new JSONObject(new String(body,StandardCharsets.UTF_8));return obj("schema","aeris.field02.workspace/1","bodyBase64",android.util.Base64.encodeToString(body,android.util.Base64.NO_WRAP),"bodySha256",Integrity02.sha(body),"modelSha256",doc.getJSONObject("mission").getString("sha256"),"hostHead",ws.getString("token"),"source","FIELD02_HOST_COMPANION_SIM_ONLY","authorityRestored",false).toString().getBytes(StandardCharsets.UTF_8);}
 private void admission(int additional)throws Exception{if(Integrity02.usage(root)+additional>Integrity02.QUOTA||root.getUsableSpace()<Integrity02.RESERVE+additional||operations>=16)throw new IOException("LOCAL_QUOTA_RESERVE_NO_AUTO_DELETE");}
 private void mirror()throws Exception{JSONObject ws=loadWorkspace();byte[]b=wrapper(ws);String h=Integrity02.sha(b);File f=new File(root,"mirror-"+h+".json");if(!f.exists()){admission(b.length);Integrity02.publish(f,b);syncDirectory();append("MIRROR_COMMITTED",obj("sha256",h,"bytes",b.length,"hostHead",head,"authorityRestored",false));}answer(true,"MIRROR_VERIFIED",obj("sha256",h,"bytes",b.length,"journalHead",journalHead).toString());}
