 private void custom(Uri u){String action=u.getHost();if(!Arrays.asList("export-workspace","import-workspace","export-artifact","status").contains(action)||u.getPath()!=null&&!u.getPath().isEmpty()&&!u.getPath().equals("/")){answer(false,"CUSTOM_URI_REJECTED","");return;}if(busy){answer(false,"SAF_BUSY","");return;}busy=true;io.execute(()->{try{if(action.equals("status")){answer(true,"LOCAL_STATUS",obj("journalHead",journalHead,"records",journalSeq,"operations",operations,"authorityRestored",false,"bytes",Integrity02.usage(root)).toString());busy=false;return;}idle();if(action.equals("import-workspace")){admission(0);pendingImportHead=loadWorkspace().getString("token");operation=UUID.randomUUID().toString();append("PICKER_PENDING",obj("id",operation,"type","import","authorityRestored",false));operations++;main.post(()->picker(false,"application/json","workspace.json"));return;}byte[]b;String name,mime;if(action.equals("export-workspace")){b=wrapper(loadWorkspace());name="AERIS-field02-workspace.json";mime="application/json";}else{String url=Integrity02.artifact(u.getQueryParameter("url"));String expected=u.getQueryParameter("sha256");name=Integrity02.filename(u.getQueryParameter("name"));if(!Integrity02.digest(expected))throw new IOException("EXPECTED_SHA_REQUIRED");b=http(URI.create(url).getRawPath(),null,Integrity02.ARTIFACT_MAX);Integrity02.verified(b,expected);mime=name.endsWith(".json")?"application/json":"application/x-tar";}admission(b.length);operation=UUID.randomUUID().toString();pendingName=name;pendingSha=Integrity02.sha(b);staged=new File(root,operation+".artifact");Integrity02.publish(staged,b);syncDirectory();append("PICKER_PENDING",obj("id",operation,"type","export","name",name,"sha256",pendingSha,"bytes",b.length,"authorityRestored",false));operations++;String type=mime;main.post(()->picker(true,type,pendingName));}catch(Exception e){failed(e);}});}
 private void picker(boolean create,String mime,String name){try{Intent i=new Intent(create?Intent.ACTION_CREATE_DOCUMENT:Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(mime);if(create)i.putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(i,create?2200:2201);}catch(Exception e){failed(e);}}
 private void failed(Exception e){try{if(operation!=null)append("UNKNOWN",obj("id",operation,"reason",e.getMessage(),"authorityRestored",false));}catch(Exception ignored){}busy=false;operation=null;answer(false,"OPERATION_NOT_CONFIRMED",e.getMessage());}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==2202){ValueCallback<Uri[]>c=chooser;chooser=null;if(c!=null)c.onReceiveValue(result==RESULT_OK&&data!=null&&data.getData()!=null?new Uri[]{data.getData()}:null);return;}if(request!=2200&&request!=2201)return;io.execute(()->{try{if(operation==null)throw new IOException("NO_PENDING_OPERATION");if(result!=RESULT_OK||data==null||data.getData()==null){append("CANCELLED",obj("id",operation,"stageRetained",true));answer(false,"SAF_CANCELLED","Không xuất/nhập; dữ liệu gốc được giữ.");return;}Uri uri=data.getData();if(!"content".equals(uri.getScheme()))throw new IOException("SAF_CONTENT_REQUIRED");idle();if(request==2200){byte[]b;try(InputStream in=new FileInputStream(staged)){b=Integrity02.read(in,Integrity02.ARTIFACT_MAX);}Integrity02.verified(b,pendingSha);try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("PROVIDER_WRITE");out.write(b);out.flush();}byte[]read;try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("PROVIDER_READ");read=Integrity02.read(in,b.length);}Integrity02.verified(read,pendingSha);append("EXPORTED_READBACK_VERIFIED",obj("id",operation,"sha256",pendingSha,"bytes",read.length,"authorityRestored",false));answer(true,"EXPORTED_READBACK_VERIFIED",obj("id",operation,"sha256",pendingSha,"bytes",read.length,"authorityRestored",false).toString());}else{byte[]b;try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("IMPORT_READ");b=Integrity02.read(in,Integrity02.WORKSPACE_MAX*2);}JSONObject w=new JSONObject(new String(b,StandardCharsets.UTF_8));if(!w.getString("schema").equals("aeris.field02.workspace/1")||w.optBoolean("authorityRestored",true))throw new IOException("WORKSPACE_SCHEMA_AUTHORITY");byte[]body=android.util.Base64.decode(w.getString("bodyBase64"),android.util.Base64.DEFAULT);if(body.length>Integrity02.WORKSPACE_MAX)throw new IOException("IMPORT_BODY_BOUND");Integrity02.verified(body,w.getString("bodySha256"));JSONObject doc=new JSONObject(new String(body,StandardCharsets.UTF_8));if(!doc.getJSONObject("mission").getString("sha256").equals(w.getString("modelSha256")))throw new IOException("IMPORT_MODEL_BINDING");JSONObject before=loadWorkspace();if(pendingImportHead==null||!before.getString("token").equals(pendingImportHead))throw new IOException("WORKSPACE_CHANGED_WHILE_PICKER_OPEN");JSONObject saved=new JSONObject(new String(http("/api/native82",obj("action","save","expected",before.getString("token"),"body",new String(body,StandardCharsets.UTF_8)),Integrity02.WORKSPACE_MAX),StandardCharsets.UTF_8));if(saved.has("result"))saved=saved.getJSONObject("result");if(!saved.optBoolean("ok"))throw new IOException("HOST_IMPORT_NOT_ACCEPTED");JSONObject after=loadWorkspace();JSONObject check=new JSONObject(new String(android.util.Base64.decode(after.getString("bodyBase64"),android.util.Base64.DEFAULT),StandardCharsets.UTF_8));if(!check.getJSONObject("mission").getString("sha256").equals(w.getString("modelSha256")))throw new IOException("IMPORT_READBACK_MODEL");append("IMPORTED_HOST_SCHEMA_CAS_VERIFIED",obj("id",operation,"bodySha256",w.getString("bodySha256"),"modelSha256",w.getString("modelSha256"),"hostHead",after.getString("token"),"authorityRestored",false));mirror();answer(true,"IMPORTED_HOST_SCHEMA_CAS_VERIFIED","Model và SHA đã kiểm; cần cấp quyền mới, không phục hồi quyền bay.");main.post(()->{if(web!=null&&!destroyed)web.reload();});}}catch(Exception e){failed(e);}finally{busy=false;operation=null;staged=null;pendingImportHead=null;}});}
 private void answer(boolean ok,String code,String message){main.post(()->{if(web==null||destroyed)return;try{JSONObject r=obj("ok",ok,"code",code,"message",message==null?"UNKNOWN":message,"authorityRestored",false);web.evaluateJavascript("window.dispatchEvent(new CustomEvent('field02Native',{detail:"+r+"}));",null);if(!ok||code.contains("EXPORTED")||code.contains("IMPORTED"))Toast.makeText(this,code+" · "+(message==null?"":message),Toast.LENGTH_LONG).show();}catch(Exception ignored){}});}
 private void lifecycle(String event){if(web!=null)main.post(()->{if(!destroyed)web.evaluateJavascript("window.field02Lifecycle&&window.field02Lifecycle("+JSONObject.quote(event)+");",null);});if(event.equals("background")||event.equals("stop"))signals.execute(()->{try{http("/api/client-session",obj("action",event,"instance",instance),65536);}catch(Exception ignored){/* Host heartbeat expiry remains mandatory; never claim background ACK. */}});}
